using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long n;
    cin >> n;

    set<long long> lucky_numbers;

    for (int d1 = 0; d1 <= 9; ++d1) {
        for (int d2 = 0; d2 <= 9; ++d2) {
            // Generate numbers of length 1 to 10
            for (int len = 1; len <= 10; ++len) {
                // Total combinations: 2^len
                // Use bitmask to represent choice of digit for each position
                // 0 -> d1, 1 -> d2
                int total_masks = 1 << len;
                for (int mask = 0; mask < total_masks; ++mask) {
                    // Check leading zero constraint
                    // Most significant bit corresponds to first digit (index len-1 in 0..len-1)
                    // Or iterate i from 0 to len-1 where i=0 is first digit.
                    // Let's say bit i corresponds to position i.
                    // First digit is position 0.
                    int first_digit_choice = (mask >> 0) & 1; // Wait, usually mask bits correspond to positions.
                    // Let's map bit i to position i.
                    // First digit is position 0.
                    // If len=1, mask has 1 bit.

                    // Determine first digit
                    int first_digit_val;
                    if (((mask >> 0) & 1) == 0) first_digit_val = d1;
                    else first_digit_val = d2;

                    if (first_digit_val == 0) continue;

                    long long current_num = 0;
                    for (int i = 0; i < len; ++i) {
                        int bit = (mask >> i) & 1;
                        int digit = (bit == 0) ? d1 : d2;
                        current_num = current_num * 10 + digit;
                    }

                    if (current_num <= n) {
                        lucky_numbers.insert(current_num);
                    }
                }
            }
        }
    }

    cout << lucky_numbers.size() << "\n";

